<?php require_once 'config/app.php'; require_once 'includes/security.php'; start_secure_session();$token=$_GET['token']??$_POST['token']??'';$error=null;$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['_csrf']??''))$error='Invalid request.';else{$p=$_POST['password']??'';$c=$_POST['confirm_password']??'';if(strlen($p)<8||$p!==$c)$error='Password must be at least 8 characters and match.';else{$pdo=db();$st=$pdo->prepare("SELECT id FROM users WHERE reset_token=? AND reset_expires>NOW() LIMIT 1");$st->execute([$token]);$u=$st->fetch();if(!$u)$error='Reset link is invalid or expired.';else{$pdo->prepare("UPDATE users SET password_hash=?,reset_token=NULL,reset_expires=NULL WHERE id=?")->execute([password_hash($p,PASSWORD_DEFAULT),$u['id']]);$success='Password updated. You can now login.';}}}}
$page_title='Reset Password';$asset_prefix='';$home_link='index.php';require 'includes/header.php';?><div class="form-wrap"><div class="form-card"><h1>Set New Password</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><a class="btn btn-primary full" href="login.php">Login</a><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>New Password<input type="password" name="password" required></label><label>Confirm Password<input type="password" name="confirm_password" required></label><button class="btn btn-primary full">Update Password</button></form><?php endif;?></div></div><?php require 'includes/footer.php';?>